 function eraserPanel(){modal('Loại tẩy',`<div class="eraser-modes">${[['stroke','Tẩy nét (nhanh)'],['partial','Tẩy cục bộ'],['precision','Tẩy chính xác']].map(([id,label])=>`<button data-erase-mode="${id}"><img class="icon-image" src="${ICON_ASSETS.eraser}" alt="" draggable="false"><span>${label}</span></button>`).join('')}</div><p class="wb-hint" id="eraseHint"></p>`,'eraser');const refresh=()=>{for(const b of dialog.querySelectorAll('[data-erase-mode]')){const active=b.dataset.eraseMode===settings.eraserMode;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));}$('#eraseHint').textContent={precision:'Tẩy từng phần nét; xử lý nặng hơn Tẩy nét.',partial:'Tẩy phần nét chạm vào vùng tròn.',stroke:'Tẩy toàn bộ nét khi chạm vào.'}[settings.eraserMode];};for(const b of dialog.querySelectorAll('[data-erase-mode]'))b.onclick=()=>{settings.eraserMode=b.dataset.eraseMode;migrateFastEraser=false;try{localStorage.setItem('bangtoan-fast-eraser-v1','1');}catch{}persist();refresh();window.dispatchEvent(new Event('bangtoan:style'));};refresh();}
