 function pencilPanel(){modal('Bút chì tiêu chuẩn',`<canvas id="pencilSample" width="640" height="220"></canvas><span class="panel-caption">CÀI ĐẶT</span><div class="pen-options"><label class="wb-check"><span>Giảm độ trễ</span><input id="pencilFast" class="studio-switch" type="checkbox"></label><label class="wb-check"><span>Giữ bút để vẽ hình</span><input id="pencilHold" class="studio-switch" type="checkbox"></label></div><p class="wb-hint">Giảm độ trễ ưu tiên phản hồi trực tiếp, giảm xử lý làm mượt. Kết nối Apple Pencil được quản lý trong Cài đặt của iPad.</p>`,'pencil');const sample=()=>{const ctx=$('#pencilSample').getContext('2d');ctx.clearRect(0,0,640,220);drawStroke(ctx,{...strokeStyle('pen'),id:'pencil-sample',size:8,color:'#64758a',points:Array.from({length:100},(_,i)=>[50+i*5.4,110+Math.sin(i/99*Math.PI*2)*45,.5])});};for(const [id,key]of [['pencilFast','pencilFast'],['pencilHold','pencilQuickShape']]){$('#'+id).checked=settings[key];$('#'+id).onchange=e=>{settings[key]=e.target.checked;persist();sample();};}sample();}
