 function textDialog(origin,existing){origin=[Math.min(origin[0],h.page().width-100),Math.min(origin[1],h.page().height-100),.5];modal(existing?'Sửa nội dung chữ':'Chèn chữ',`<label class="wb-field">Nội dung<textarea id="wbText" rows="5" maxlength="5000" placeholder="Nhập nội dung để giảng…"></textarea></label><div class="wb-two"><label>Cỡ chữ<input id="wbFontSize" type="number" min="10" max="120" value="${existing?.fontSize||28}"></label><label class="wb-check"><input id="wbBold" type="checkbox"> In đậm</label></div><p id="wbTextError" class="danger-text"></p><button id="wbInsertText" class="primary wb-wide">Lưu chữ</button>`);$('#wbText').value=existing?.text||'';$('#wbBold').checked=existing?.bold||false;$('#wbInsertText').onclick=()=>{const text=$('#wbText').value.trim(),size=+$('#wbFontSize').value;if(!text||!Number.isFinite(size)||size<10||size>120){$('#wbTextError').textContent='Nhập nội dung và cỡ chữ từ 10 đến 120.';return;}const ctx=h.canvas().getContext('2d');ctx.save();ctx.font=`${$('#wbBold').checked?'600':'400'} ${size}px -apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif`;const max=Math.max(80,h.page().width-origin[0]-30),lines=[];for(const paragraph of text.split('\n')){let line='';for(const ch of paragraph){if(ctx.measureText(line+ch).width>max&&line){lines.push(line);line=ch;}else line+=ch;}lines.push(line);}if(lines.join('\n').length>5000){ctx.restore();$('#wbTextError').textContent='Nội dung quá dài. Hãy chia thành nhiều khối chữ.';return;}const width=Math.max(20,...lines.map(l=>ctx.measureText(l).width)),height=lines.length*size*1.35;ctx.restore();if(origin[1]+height>h.page().height){$('#wbTextError').textContent='Chữ vượt quá chiều cao trang. Hãy giảm cỡ chữ hoặc chia nội dung.';return;}const s={id:existing?.id||h.id(),kind:'text',color:$('#color').value,size:3,points:[origin],text:lines.join('\n'),fontSize:size,bold:$('#wbBold').checked,boxWidth:Math.min(5000,width),boxHeight:height};const ok=existing?h.op('edit',{ids:[s.id],strokes:[s]}):h.op('stroke',{stroke:s});if(ok){dialog.close();selected=new Set([s.id]);h.selectTool('select',false);refresh();}};$('#wbText').focus();}
 const imageInput=document.createElement('input');imageInput.type='file';imageInput.accept='image/png,image/jpeg';imageInput.hidden=true;document.body.append(imageInput);imageInput.onchange=async()=>{const file=imageInput.files[0];imageInput.value='';if(!file)return;if(!h.ready())return h.toast('Bật chế độ viết và chờ gửi xong nét trước khi chèn ảnh.');if(file.size>80*1024*1024)return h.toast('Ảnh vượt quá 80 MB.');const p=h.page();h.busy(true);try{const asset=await h.upload(file),im=await h.image(asset),scale=Math.min(Math.max(40,p.width-120)/im.width,Math.max(40,p.height-120)/im.height,600/im.width),w=im.width*scale,height=im.height*scale;const s={id:h.id(),kind:'image',asset,color:'#22354b',size:1,points:[[60,60,.5],[60+w,60+height,.5]]};if(h.op('stroke',{stroke:s,pageId:p.id})){selected=new Set([s.id]);h.selectTool('select',false);refresh();}}catch(e){h.toast(e.message);}finally{h.busy(false);}};
 function selectionAction(action){const list=items();if(action==='close'){selected.clear();if(autoSelected){autoSelected=false;h.resumePen();}refresh();return;}if(action==='paste'){if(!clipboard.length)return h.toast('Chưa sao chép nội dung.');return paste(clipboard);}if(!list.length)return;if(action==='copy'){clipboard=structuredClone(list);h.toast('Đã sao chép nội dung.');return;}if(action==='duplicate')return paste(list);if(action==='transform')return transformPanel(list);if(action==='text'&&list.length===1&&list[0].kind==='text')return textDialog(list[0].points[0],list[0]);if(action==='cut')clipboard=structuredClone(list);if(['cut','delete'].includes(action)&&h.op('edit',{ids:list.map(s=>s.id),strokes:[]})){selected.clear();refresh();}}
 function transformPanel(list){
  if(!h.ready())return h.toast('Chờ gửi xong thao tác trước khi biến đổi.');
  const original=structuredClone(list),pageId=h.page().id;let result=null;
  modal('Xoay / Kéo giãn',`<canvas id="wbTransformPreview" width="480" height="190"></canvas>${input('wbRotate','Xoay thêm (°)',0,-180,180)}<div class="wb-two"><button id="wbRotateLeft" class="wb-wide">↶ 15°</button><button id="wbRotateRight" class="wb-wide">↷ 15°</button></div>${input('wbScaleX','Chiều ngang (%)',100,10,300)}${input('wbScaleY','Chiều dọc (%)',100,10,300)}<label class="wb-check"><input id="wbLockRatio" type="checkbox"> Giữ tỉ lệ ngang / dọc</label><p class="wb-hint">Kéo ngang và dọc độc lập để đổi tỉ lệ. Độ dày nét giữ nguyên. Chỉ lưu khi bấm Áp dụng; đóng cửa sổ sẽ hủy.</p><p id="wbTransformError" class="danger-text"></p><button id="wbResetTransform" class="wb-wide">Đặt lại</button><button id="wbApplyTransform" class="primary wb-wide">Áp dụng</button>`);
  $('#wbClose').textContent='Hủy';
  const preview=()=>{
   for(const id of ['wbRotate','wbScaleX','wbScaleY'])$('#'+id+'Value').textContent=$('#'+id).value;
   try{result=transformVectorItems(original,{angle:+$('#wbRotate').value,scaleX:+$('#wbScaleX').value/100,scaleY:+$('#wbScaleY').value/100,width:h.page().width,height:h.page().height});$('#wbTransformError').textContent='';$('#wbApplyTransform').disabled=false;}catch(e){result=null;$('#wbTransformError').textContent=e.message;$('#wbApplyTransform').disabled=true;}
   const canvas=$('#wbTransformPreview'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#f5f7fb';ctx.fillRect(0,0,canvas.width,canvas.height);
   if(result){const box=unionBounds(result),scale=Math.min((canvas.width-40)/Math.max(1,box.w),(canvas.height-30)/Math.max(1,box.h));ctx.save();ctx.translate((canvas.width-box.w*scale)/2,(canvas.height-box.h*scale)/2);ctx.scale(scale,scale);ctx.translate(-box.x,-box.y);for(const s of result)drawStroke(ctx,s);ctx.restore();}
  };
  for(const id of ['wbRotate','wbScaleX','wbScaleY'])$('#'+id).oninput=()=>{if($('#wbLockRatio').checked&&id!=='wbRotate')$('#'+(id==='wbScaleX'?'wbScaleY':'wbScaleX')).value=$('#'+id).value;preview();};
  $('#wbLockRatio').onchange=()=>{if($('#wbLockRatio').checked)$('#wbScaleY').value=$('#wbScaleX').value;preview();};
  for(const [id,step]of [['wbRotateLeft',-15],['wbRotateRight',15]])$('#'+id).onclick=()=>{$('#wbRotate').value=Math.max(-180,Math.min(180,+$('#wbRotate').value+step));preview();};
  $('#wbResetTransform').onclick=()=>{$('#wbRotate').value=0;$('#wbScaleX').value=$('#wbScaleY').value=100;preview();};
  $('#wbApplyTransform').onclick=()=>{if(!result||h.page().id!==pageId)return;if(h.op('edit',{pageId,ids:original.map(s=>s.id),strokes:result})){dialog.close();refresh();}};
  preview();
 }
 function paste(list){const box=unionBounds(list),p=h.page(),target={...box,x:Math.min(p.width-box.w,box.x+30),y:Math.min(p.height-box.h,box.y+30)},copies=transformItems(list,box,target).map(s=>({...s,id:h.id()}));if(h.op('edit',{ids:[],strokes:copies})){selected=new Set(copies.map(s=>s.id));refresh();}}
 tray.addEventListener('click',e=>{const a=e.target.closest('[data-selection]')?.dataset.selection;if(a)selectionAction(a);});
 function onTool(t,same){if(!same&&dialog.open)dialog.close();if(t!=='eraser')eraserCursor=null;if(t!=='select'||same)autoSelected=false;if(tool==='pen')settings.penColor=$('#color').value;if(tool==='highlighter')settings.highlightColor=$('#color').value;if(['pen','highlighter'].includes(t))previous=t;tool=t;if(!same&&['pen','highlighter'].includes(t)){$('#color').value=t==='pen'?settings.penColor:settings.highlightColor;h.style();}if(t!=='select'){selected.clear();tray.hidden=true;}$('#activeToolName').textContent={pen:'Bút',eraser:'Tẩy',highlighter:'Đánh dấu',select:'Khoanh chọn',shape:'Hình vẽ',text:'Chèn chữ',image:'Ảnh',crop:'Cắt câu',hand:'Kéo trang',laser:'Laser'}[t]||'';if(same){if(t==='pen')penPanel();else if(t==='highlighter')penPanel(true);else if(t==='eraser')eraserPanel();else if(t==='select')selectionPanel();else if(t==='shape')shapesPanel();}h.live();}
 function style(){if(!h.page())return;syncPageUnits();if(tool==='pen'){settings.penSize=+$('#size').value;settings.penSizeMm=clampMm(sizeToMm(settings.penSize,h.page()));}$('#sizeMm').value=settings.penSizeMm;$('#sizeMmValue').textContent=settings.penSizeMm.toFixed(2)+' mm';if(tool==='pen')settings.penColor=$('#color').value;if(tool==='highlighter')settings.highlightColor=$('#color').value;persist();if(tool==='select'&&selected.size&&h.ready()){const list=items().filter(s=>s.kind!=='image'&&s.color!==$('#color').value);if(list.length)h.op('editStyle',{updates:list.map(s=>({id:s.id,color:$('#color').value}))});}}
 function strokeStyle(t){return t==='highlighter'?{kind:'ink',size:Math.min(40,+$('#size').value*4),opacity:settings.highlightOpacity,penStyle:'ball',dashed:false}:{kind:'ink',smoothing:settings.penStyle==='pencil'&&settings.pencilFast?0:1,inkVersion:2,penModel:settings.penStyle==='pencil'?4:24,penTuning:{stabilizer:1,stability:settings.penStyle==='pencil'&&settings.pencilFast?0:settings.stability,taper:settings.penStyle==='brush'?.85:settings.penStyle==='fountain'?settings.nibTaper:0,sensitivity:settings.pressureSensitivity,flatness:settings.penStyle==='fountain'?settings.nibFlatness:0},opacity:settings.opacity,penStyle:settings.penStyle,dashed:settings.dashed,dotted:!!settings.dotted};}
 function draw(ctx){if(tool==='eraser'&&eraserCursor){ctx.save();ctx.beginPath();ctx.arc(eraserCursor[0],eraserCursor[1],eraseRadius(),0,Math.PI*2);ctx.fillStyle='#ffffff1a';ctx.fill();ctx.strokeStyle='#647386';ctx.lineWidth=1.2/(h.scale()||1);ctx.stroke();ctx.restore();}if(laser){ctx.save();ctx.shadowColor='#ff203c';ctx.shadowBlur=12;drawStroke(ctx,laser);ctx.restore();}if(gesture?.type==='moveRaster'){const g=gesture;g.raster?.draw(ctx,g.dx,g.dy);ctx.save();ctx.translate(g.dx,g.dy);paintSelection(ctx,g.original,canvasScale());ctx.restore();return;}if(gesture?.type==='erase'){const g=gesture;if(g.rasterCanvas){ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(g.rasterCanvas,0,0);ctx.restore();}else if(g.preview.length){if(!g.previewCanvas||g.previewVersion!==g.version){const source=h.canvas();g.previewCanvas??=document.createElement('canvas');g.previewCanvas.width=source.width;g.previewCanvas.height=source.height;const c=g.previewCanvas.getContext('2d');c.setTransform(source.width/h.page().width,0,0,source.height/h.page().height,0,0);for(const s of g.preview)drawStroke(c,s);g.previewVersion=g.version;}ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(g.previewCanvas,0,0);ctx.restore();}}else if(gesture?.preview)for(const s of gesture.preview)drawStroke(ctx,s);if(gesture?.type==='shape')drawStroke(ctx,gesture.item);if(gesture?.type==='select'){const a=gesture.start,b=gesture.end;ctx.save();ctx.strokeStyle='#448ee9';ctx.fillStyle='#448ee912';ctx.lineWidth=2;ctx.setLineDash([7,5]);ctx.beginPath();if(settings.selectionMode==='free'){ctx.moveTo(gesture.path[0][0],gesture.path[0][1]);for(const p of gesture.path)ctx.lineTo(p[0],p[1]);ctx.closePath();}else ctx.rect(Math.min(a[0],b[0]),Math.min(a[1],b[1]),Math.abs(b[0]-a[0]),Math.abs(b[1]-a[1]));ctx.fill();ctx.stroke();ctx.restore();}
 const list=gesture?.preview||items(),box=unionBounds(list);if(tool==='select'&&box){
  if(list.every(s=>!['text','image'].includes(s.kind)))paintSelection(ctx,list,canvasScale());
  else{ctx.save();ctx.strokeStyle='#3d8de7';ctx.lineWidth=1.7;ctx.setLineDash([6,4]);ctx.strokeRect(box.x-5,box.y-5,box.w+10,box.h+10);ctx.setLineDash([]);ctx.fillStyle='white';ctx.fillRect(box.x+box.w-4,box.y+box.h-4,12,12);ctx.strokeRect(box.x+box.w-4,box.y+box.h-4,12,12);ctx.restore();}
 }}
 function canvasScale(){return h.canvas().getBoundingClientRect().width/h.page().width||1;}
 function selectCreated(id){h.selectTool('select',false);selected=new Set([id]);autoSelected=true;refresh();h.changed();h.toast('Kéo nút để chỉnh hình · Chạm ngoài để viết tiếp');}

